// DASHBOARD — missing files fix (notifications + billing + coexistence, all latest)
import { writeFileSync, mkdirSync, existsSync } from "fs";
import { dirname } from "path";
import { execSync } from "child_process";
if (!existsSync("src/app/(app)/layout.js")) { console.error("\n  Galat folder! Dashboard folder mein chalao.\n"); process.exit(1); }
const files = {"public/badge-96.png":"","public/icon-192.png":"","public/icon-512.png":"","public/sw.js":"","src/app/(app)/ai-front-desk/page.js":"","src/app/(app)/billing/page.js":"","src/app/(app)/connect-whatsapp/page.js":"","src/app/(app)/dashboard/page.js":"","src/app/(app)/knowledge/page.js":"","src/app/(app)/layout.js":"","src/app/(app)/marketing/page.js":"","src/app/(app)/notifications/page.js":"","src/app/(app)/services/page.js":"","src/app/(app)/team/page.js":"","src/app/api/stripe/webhook/route.js":"","src/app/apple-icon.png":"","src/app/manifest.js":"","src/components/AiFrontDeskForm.js":"","src/components/BillingToast.js":"","src/components/CalendarView.js":"","src/components/CampaignsManager.js":"","src/components/ConnectWhatsApp.js":"","src/components/KnowledgeManager.js":"","src/components/NotificationBell.js":"","src/components/NotificationSettings.js":"","src/components/PushBell.js":"","src/components/ServicesManager.js":"","src/components/StripeUpgradeButton.js":"","src/components/TeamManager.js":"","src/components/Toaster.js":"","src/components/WhatsAppSetupGuide.js":"","src/components/notif-meta.js":"","src/lib/ai-frontdesk-actions.js":"","src/lib/campaign-actions.js":"","src/lib/knowledge-actions.js":"","src/lib/notification-actions.js":"","src/lib/notify.js":"","src/lib/push-actions.js":"","src/lib/services-actions.js":"","src/lib/stripe-actions.js":"","src/lib/team-actions.js":"","src/lib/toast.js":"","src/lib/use-push.js":"","src/lib/whatsapp-actions.js":""};
for (const [p, b64] of Object.entries(files)) { mkdirSync(dirname(p), { recursive: true }); writeFileSync(p, Buffer.from(b64, "base64")); console.log("  wrote " + p); }
console.log("\n  Installing web-push ...");
try { execSync("npm install web-push@3.6.7 --save", { stdio: "inherit" }); } catch (e) { console.error("  npm install fail — khud chalao: npm install web-push"); }
console.log("\nDone. Ab: git add .  ->  git commit -m \"Fix build: missing files\"  ->  git push");
